function crossing_call(string $method,string $path,?array $payload=null):array{$headers="Content-Type: application/json\r\nCookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n";$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$body=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$status=(int)substr($http_response_header[0]??'HTTP/1.1 500',9,3);return['status'=>$status,'raw'=>is_string($body)?$body:'','body'=>is_string($body)?json_decode($body,true):null];}
function crossing_expect(int $status,array $result,string $label):array{if($result['status']!==$status){fwrite(STDERR,"FAIL $label HTTP {$result['status']} {$result['raw']}\n");exit(1);}echo"PASS $label HTTP $status\n";return is_array($result['body'])?$result['body']:[];}
