   $pdo->exec('DROP TABLE crossings');crossing_expect(200,crossing_call('GET','/api/crossings?session_id='.$sessionId),'pre-013 crossings read remains HTTP 200');$exportUnavailable=crossing_call('GET','/api/export.csv?type=crossings&session_id='.$sessionId);crossing_expect(503,$exportUnavailable,'pre-013 crossing CSV export gives migration guidance');crossing_check(str_contains($exportUnavailable['raw'],'migration 013'),'pre-013 export explains required migration');$legacyRead=crossing_expect(200,crossing_call('GET','/api/crossings/'.$crossingId),'pre-013 single crossing read remains HTTP 200');crossing_check($legacyRead['schema_available']===false,'pre-013 read reports unavailable schema without query failure');$write=crossing_call('POST','/api/crossings/start',['session_id'=>$sessionId,'node_id'=>'H1','crossing_no'=>4,'gate_no'=>4,'gate_side'=>'FIELD']);crossing_expect(503,$write,'pre-013 crossing write returns migration guidance');crossing_check(str_contains($write['raw'],'migration 013'),'pre-013 write explains required migration');$pdo->exec(rtrim(trim(file_get_contents(dirname(__DIR__).'/sql/migrations/013_crossings.sql')),';'));echo"PASS pre-013 crossings table restored on disposable scratch DB.\n";
